export function getManufacturingSpokePage(
  href: string
): ManufacturingSpokePageContent {
  const page = MANUFACTURING_SPOKE_PAGES.find((item) => item.href === href);
  if (!page) {
    throw new Error(`Unknown manufacturing spoke page: ${href}`);
  }
  return page;
}

