export function getFinancialServicesSpokePage(
  href: string
): VerticalSpokePageContent {
  const page = FINANCIAL_SERVICES_SPOKE_PAGES.find((item) => item.href === href);
  if (!page) {
    throw new Error(`Unknown financial-services spoke page: ${href}`);
  }
  return page;
}
